const body = $json.body ?? $json;
const issue = body.issue ?? {};
const fields = issue.fields ?? {};

const labels = fields.labels ?? [];
const environment = typeof fields.environment === 'string'
  ? fields.environment
  : JSON.stringify(fields.environment ?? '');

const isProductionBug =
  (fields.issuetype?.name ?? '').toLowerCase() === 'bug' &&
  (
    environment.toLowerCase().includes('production') ||
    labels.some(l => String(l).toLowerCase() === 'production')
  );

return [{
  json: {
    isProductionBug,
    issueKey: issue.key ?? '',
    issueId: issue.id ?? '',
    summary: fields.summary ?? '',
    projectKey: fields.project?.key ?? '',
    issueType: fields.issuetype?.name ?? '',
    environment,
    labels,
    priority: fields.priority?.name ?? '',
    severity: fields.severity?.name ?? fields.customfield_severity ?? '',
    status: fields.status?.name ?? '',
    reporter: fields.reporter?.displayName ?? '',
    assignee: fields.assignee?.displayName ?? '',
    created: fields.created ?? '',
    updated: fields.updated ?? '',
    rawIssue: issue
  }
}];

return [{
  json: {
    ...$json,
    config: {
      jiraBaseUrl: 'https://YOUR-DOMAIN.atlassian.net',
      jiraProjectKey: 'YOUR_PROJECT',
      productionLabel: 'production',
      excelFileName: 'Production_RCA_Sample.xlsx',
      rcaRegisterSheet: 'RCA Register',
      aiModel: 'YOUR_AI_MODEL',
      missingValue: 'Not Available in Jira - Investigation Required',
      investigationRequired: 'Investigation Required'
    }
  }
}];

const base = $('04_Load_Configuration').item.json;
const issue = $('05_Get_Jira_Issue').item.json;
const comments = $('06_Get_Jira_Comments').item.json;
const history = $('07_Get_Jira_History').item.json;

function adfToText(value) {
  if (!value) return '';
  if (typeof value === 'string') return value;
  if (Array.isArray(value)) return value.map(adfToText).join(' ');
  if (typeof value === 'object') {
    if (value.text) return value.text;
    return Object.values(value).map(adfToText).join(' ');
  }
  return String(value);
}

const f = issue.fields ?? {};
const commentList = (comments.comments ?? []).map(c => adfToText(c.body)).filter(Boolean);

return [{
  json: {
    jira: {
      issueKey: issue.key ?? base.issueKey,
      issueId: issue.id ?? base.issueId,
      summary: f.summary ?? base.summary,
      description: adfToText(f.description),
      issueType: f.issuetype?.name ?? base.issueType,
      status: f.status?.name ?? base.status,
      priority: f.priority?.name ?? base.priority,
      severity: f.severity?.name ?? f.customfield_severity ?? base.severity,
      reporter: f.reporter?.displayName ?? base.reporter,
      assignee: f.assignee?.displayName ?? base.assignee,
      created: f.created ?? base.created,
      updated: f.updated ?? base.updated,
      resolved: f.resolutiondate ?? '',
      project: f.project?.key ?? base.projectKey,
      components: (f.components ?? []).map(x => x.name),
      labels: f.labels ?? base.labels,
      fixVersions: (f.fixVersions ?? []).map(x => x.name),
      affectedVersions: (f.versions ?? []).map(x => x.name),
      environment: adfToText(f.environment) || base.environment,
      comments: commentList,
      changelog: history.changelog ?? []
    },
    config: base.config
  }
}];

const data = $json;
const blockedKeys = [
  'password', 'passwd', 'pwd', 'authorization',
  'access_token', 'refresh_token', 'client_secret',
  'api_token', 'secret'
];

function redact(value) {
  if (typeof value !== 'string') return value;
  let output = value;
  for (const key of blockedKeys) {
    const re = new RegExp(`(${key}\\s*[:=]\\s*)[^\\s,;]+`, 'ig');
    output = output.replace(re, '$1[REDACTED]');
  }
  return output;
}

const sanitized = JSON.parse(JSON.stringify(data));
sanitized.jira.description = redact(sanitized.jira.description);
sanitized.jira.comments = sanitized.jira.comments.map(redact);

return [{ json: sanitized }];

/*
EXPECTED AI OUTPUT:
The next AI node should return the JSON described in 10_Prepare_AI_RCA_Prompt.

This placeholder Code node validates the expected structure after you connect
your preferred n8n AI model.

Replace the source below with the actual AI node output.
*/
const raw = $json.aiOutput ?? $json;
let rca = raw;

if (typeof raw === 'string') {
  const cleaned = raw.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim();
  rca = JSON.parse(cleaned);
}

if (!rca.document_control || !rca.incident_summary || !rca.root_cause) {
  throw new Error('Invalid RCA JSON: required sections are missing.');
}

return [{ json: { ...$json, rca } }];

const d = $json;
const r = d.rca;
const investigate = d.config.investigationRequired;
const missing = d.config.missingValue;

function safe(v, fallback = missing) {
  return v === undefined || v === null || v === '' ? fallback : v;
}

r.root_cause = r.root_cause || {};
r.root_cause.technical_root_cause =
  safe(r.root_cause.technical_root_cause, 'Not Determined - Investigation Required');

if (r.root_cause.technical_root_cause !== 'Not Determined - Investigation Required') {
  r.root_cause.root_cause_statement = safe(r.root_cause.root_cause_statement, investigate);
}

r.qa_escape_analysis = r.qa_escape_analysis || {};
r.qa_escape_analysis.escape_point =
  safe(r.qa_escape_analysis.escape_point, investigate);

r.document_control = r.document_control || {};
r.document_control.rca_id =
  r.document_control.rca_id || `RCA-${d.jira.issueKey}`;
r.document_control.defect_id =
  r.document_control.defect_id || d.jira.issueKey;

return [{ json: { ...d, rca: r } }];

/*
Excel integration placeholder.

Recommended implementation:
- Use Microsoft Excel 365 node if the workbook is in OneDrive/SharePoint.
- Or use Google Sheets if you choose to store RCA data in Sheets.
- Or use a Code/Spreadsheet File approach if the workbook is local.

Lookup key:
Jira Issue Key = {{$json.jira.issueKey}}

If found: update existing RCA.
If not found: create new RCA.

Recommended target sheet: RCA Register.
*/
return [{
  json: {
    ...$json,
    excelLookupKey: $json.jira.issueKey,
    excelAction: 'CREATE_OR_UPDATE'
  }
}];

/*
Replace this placeholder with the actual Excel lookup result.

Expected:
existingRca = true/false
excelRowId = row identifier when updating
*/
return [{
  json: {
    ...$json,
    existingRca: Boolean($json.existingRca),
    excelRowId: $json.excelRowId ?? null
  }
}];

/*
EXCEL UPDATE PLACEHOLDER

Map $json.rca into the existing RCA row identified by $json.excelRowId.

Use:
- Jira Issue Key as unique key
- Preserve Created Date
- Update Last Updated
- Update RCA fields from latest evidence
- Do not overwrite confirmed historical information unnecessarily
*/
return [{
  json: {
    ...$json,
    action: 'UPDATE_RCA',
    excelStatus: 'PENDING_EXCEL_NODE_CONFIGURATION',
    lastUpdated: new Date().toISOString()
  }
}];

/*
EXCEL CREATE PLACEHOLDER

Create a new row in RCA Register.

Primary key:
Jira Issue Key

Map all required RCA Register columns from $json.rca.
*/
return [{
  json: {
    ...$json,
    action: 'CREATE_RCA',
    excelStatus: 'PENDING_EXCEL_NODE_CONFIGURATION',
    createdDate: new Date().toISOString(),
    lastUpdated: new Date().toISOString()
  }
}];

return [{
  json: {
    timestamp: new Date().toISOString(),
    workflowExecutionId: $execution.id,
    jiraIssueKey: $json.jira.issueKey,
    action: $json.action ?? 'UNKNOWN',
    rcaStatus: $json.rca?.document_control?.rca_status ?? 'Investigation Required',
    aiStatus: 'Processed',
    excelStatus: $json.excelStatus ?? 'Unknown',
    numberOfFieldsUpdated: 0,
    workflowDurationNote: 'Calculated by n8n execution metadata'
  }
}];

const j = $json.jira ?? {};
const r = $json.rca ?? {};
return [{
  json: {
    message: `Production RCA automation completed.
Jira Issue: ${j.issueKey ?? ''}
Summary: ${j.summary ?? ''}
RCA Status: ${r.document_control?.rca_status ?? 'Investigation Required'}
Excel Status: ${$json.excelStatus ?? 'Unknown'}`,
    jiraIssueKey: j.issueKey ?? '',
    rcaStatus: r.document_control?.rca_status ?? 'Investigation Required'
  }
}];
